//! Reconstruction of the Delia player entity from the NA x64 `client.dll`
//! (`C_HeroesPlayerDelia`) and `server.dll` (`CHeroesPlayerDelia`).
//!
//! Source build: SHA-256 `0be9bfa584761111…` (client) and `9f674dbab6f31b0d…`
//! (server), image base `0x180000000`. Every function names the virtual slot and
//! the RVA it was read from; `docs/evidence/client/na-x64-delia-entity.json`
//! (regenerated by `scripts/reverse/na_x64_delia_entity.py`) lists all slots.
//!
//! Engine calls that this crate does not reconstruct are behind the
//! [`client::ClientHost`] and [`server::ServerHost`] traits, named after the
//! callee RVA. Names of slots and fields are inferred from their strings and
//! uses; where the meaning is open the name keeps the slot number.

pub mod action_event;
pub mod client;
pub mod condition;
pub mod layout;
pub mod protected;
pub mod server;
